pub fn fibonacci(n: usize) -> Vec<i32> {
    // Given n >= 2, we know there are at least two Fibonacci numbers to generate.
    // Pre-allocate a vector of length n to avoid reallocations.
    let mut ret = Vec::with_capacity(n);

    // Base cases
    ret.push(0); // F(0)
    ret.push(1); // F(1)

    // Build the sequence up to F(n-1)
    for i in 2..n {
        // Safe to index because we've already pushed i elements.
        let next = ret[i - 1].wrapping_add(ret[i - 2]);
        ret.push(next);
    }

    ret
}

